{
  "name": "bootable-site",
  "private": true,
  "type": "module",
  "scripts": {
    "predev": "node sync-assets.mjs",
    "dev": "astro dev --host",
    "prebuild": "node sync-assets.mjs",
    "build": "astro build",
    "preview": "astro preview --host"
