            candidate
                .path()
                .ends_with(".sign")
                .then(|| DEBIAN.signature.to_vec())
        },
    )
    .expect("authenticate");
    assert!(matches!(result.signature, ManifestSignature::Verified(_)));
    assert_eq!(requested.borrow().len(), 2);
}

